const { chromium } = require('playwright');
const http = require('http');

const CDP_PORT = 9222;

async function checkPortOpen(port) {
    return new Promise((resolve) => {
        const req = http.get(`http://localhost:${port}/json/version`, (res) => {
            resolve(res.statusCode === 200);
        });
        req.on('error', () => {
            resolve(false);
        });
    });
}

async function run() {
    console.log(`[1] 正在检查 CDP 端口 ${CDP_PORT} 是否开放...`);
    console.log(`提示: 请确保你已经用 \`Trae CN.exe --remote-debugging-port=${CDP_PORT}\` 启动了 Trae。`);

    const isOpen = await checkPortOpen(CDP_PORT);
    if (!isOpen) {
        console.error(`❌ 连接失败: 无法在 http://localhost:${CDP_PORT} 找到活动的 Trae 调试端点。`);
        console.log(`请手动在终端输入以下命令启动 Trae:`);
        console.log(`"D:\\Programs\\Trae CN\\Trae CN.exe" --remote-debugging-port=${CDP_PORT}`);
        console.log(`(请根据你的实际安装路径调整)`);
        process.exit(1);
    }

    console.log(`✅ 成功检测到 CDP 调试端点，开始连接 Playwright...`);

    try {
        const browser = await chromium.connectOverCDP(`http://localhost:${CDP_PORT}`);
        console.log(`✅ Playwright 连接成功！获取到的 Context 数量: ${browser.contexts().length}`);

        // 查找可能包含 Trae UI 的 Context
        let targetPage = null;
        for (const context of browser.contexts()) {
            for (const page of context.pages()) {
                const title = await page.title();
                console.log(`🔍 扫描到页面: [${title}] URL: ${page.url()}`);

                // Trae 的主窗口名称通常包含 "Trae" 或者是主程序的 HTML (例如 vscode 的 workbench)
                if (title.includes('Trae') || page.url().includes('workbench.html')) {
                    targetPage = page;
                    console.log(`🎯 锁定可能的目标页面: [${title}]`);
                }
            }
        }

        if (!targetPage) {
            console.log(`⚠️ 未找到明确的 Trae 工作台页面，将随机选取第一个进行 DOM 验证...`);
            targetPage = browser.contexts()[0].pages()[0];
        }

        if (targetPage) {
            console.log(`[2] 准备对目标页面进行简单交互测试...`);
            // 简单拿一下页面的 body
            const bodyHtml = await targetPage.locator('body').innerHTML();
            console.log(`📄 成功读取页面 DOM 树，内容长度: ${bodyHtml.length}`);

            // TODO: 在这里添加寻找输入 Chat 框的精确逻辑
            // 例如: await targetPage.locator('textarea[placeholder*="Ask"]').fill('Hello Trae from CDP!');
            // console.log(`⌨️ 已尝试注入文本！`);
        }

        await browser.close();
        console.log(`🎉 POC 断开连接，测试完毕。结论: CDP 方案 [畅通]。`);
    } catch (err) {
        console.error(`❌ 连接过程出错:`, err);
    }
}

run();
